// ==================== Correção Ortográfica via Claude API ====================

async function corrigirOrtografia(texto) {
  if (!texto || texto.trim().length < 10) return texto;
  try {
    // Desativado: a chave da API não pode ficar no código do navegador (qualquer
    // pessoa conseguiria copiá-la). Para ativar, a chamada precisa passar por um
    // servidor próprio (ex.: função serverless na Vercel) que guarde a chave.
    const apiKey = "";
    if (!apiKey) return texto;

    const response = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { 
        "Content-Type": "application/json",
        "x-api-key": apiKey
      },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        max_tokens: 1000,
        messages: [{
          role: "user",
          content: `Corrija APENAS os erros de acentuação e ortografia do texto abaixo. 
Não altere o conteúdo, o estilo ou a estrutura das frases.
Retorne SOMENTE o texto corrigido, sem explicações, sem aspas, sem prefixos.

Texto: ${texto}`
        }]
      })
    });

    if (!response.ok) {
      return texto;
    }

    const data = await response.json();
    const corrigido = data?.content?.[0]?.text?.trim();
    return corrigido || texto;
  } catch {
    return texto; // em caso de erro, retorna o texto original
  }
}

function useCorrecaoOrtografica(value, onChange) {
  const [corrigindo, setCorrigindo] = useState(false);
  const [corrigido, setCorrigido] = useState(false);
  const timeoutRef = useRef(null);

  const handleBlur = async () => {
    if (!value || value.trim().length < 10 || corrigindo) return;

    // Limpar timeout anterior para evitar múltiplas chamadas
    if (timeoutRef.current) clearTimeout(timeoutRef.current);

    // Debounce: esperar 800ms antes de chamar a API
    timeoutRef.current = setTimeout(async () => {
      setCorrigindo(true);
      setCorrigido(false);
      const novo = await corrigirOrtografia(value);
      setCorrigindo(false);
      if (novo !== value) {
        onChange(novo);
        setCorrigido(true);
        setTimeout(() => setCorrigido(false), 2500);
      }
    }, 800);
  };

  // Cleanup ao desmontar
  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
        timeoutRef.current = null;
      }
    };
  }, []);

  return { handleBlur, corrigindo, corrigido };
}

// ==================== Firebase ====================
// As chaves ficam nas variáveis de ambiente da Vercel (Settings → Environment
// Variables). No Create React App elas PRECISAM começar com REACT_APP_.
// Forma mais simples: uma única variável REACT_APP_FIREBASE_CONFIG com o bloco
// "firebaseConfig" copiado do console do Firebase (botão de copiar), sem editar.
// Se ela não existir, usa as 6 variáveis separadas.
function lerConfigColada(texto) {
  const config = {};
  if (!texto) return config;
  const padrao = /([A-Za-z]+)\s*["']?\s*:\s*["']([^"']+)["']/g;
  let m;
  while ((m = padrao.exec(texto)) !== null) config[m[1]] = m[2].trim();
  return config;
}
const configColada = lerConfigColada(process.env.REACT_APP_FIREBASE_CONFIG);
const firebaseConfig = {
  apiKey: configColada.apiKey || process.env.REACT_APP_FIREBASE_API_KEY,
  authDomain: configColada.authDomain || process.env.REACT_APP_FIREBASE_AUTH_DOMAIN,
  projectId: configColada.projectId || process.env.REACT_APP_FIREBASE_PROJECT_ID,
  storageBucket: configColada.storageBucket || process.env.REACT_APP_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: configColada.messagingSenderId || process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID,
  appId: configColada.appId || process.env.REACT_APP_FIREBASE_APP_ID,
};
const FIREBASE_CONFIGURADO = !!(firebaseConfig.apiKey && firebaseConfig.projectId && firebaseConfig.authDomain);

let auth = null;
let db = null;
if (FIREBASE_CONFIGURADO) {
  const firebaseApp = initializeApp(firebaseConfig);
  auth = getAuth(firebaseApp);
  auth.languageCode = "pt-BR"; // e-mails do Firebase (ex.: redefinir senha) em português
  try {
    // Cache no aparelho: o app continua funcionando sem internet e sincroniza depois
    db = initializeFirestore(firebaseApp, {
      localCache: persistentLocalCache({ tabManager: persistentMultipleTabManager() }),
      ignoreUndefinedProperties: true, // campos vazios (undefined) não travam a gravação
    });
  } catch {
    // Navegador sem suporte ao cache (ex.: aba anônima): funciona só online
    db = initializeFirestore(firebaseApp, { ignoreUndefinedProperties: true });
  }
}

// ── Imagens ──────────────────────────────────────────────────────────────────
// Toda imagem anexada é reduzida antes de entrar no laudo (lado máximo 1280 px,
// JPEG, até ~250 KB). Assim cabe no Firestore e não pesa no celular.
function lerImagemComprimida(file, { ladoMax = 1280, bytesMax = 250000 } = {}) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      URL.revokeObjectURL(url);
      let lado = ladoMax;
      let qualidade = 0.8;
      let resultado = "";
      for (let tentativa = 0; tentativa < 8; tentativa++) {
        const escala = Math.min(1, lado / Math.max(img.width, img.height));
        const canvas = document.createElement("canvas");
        canvas.width = Math.round(img.width * escala);
        canvas.height = Math.round(img.height * escala);
        const ctx = canvas.getContext("2d");
        ctx.fillStyle = "#fff"; // fundo branco para PNG transparente (logos, assinaturas)
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resultado = canvas.toDataURL("image/jpeg", qualidade);
        if (resultado.length * 0.75 <= bytesMax) break;
        if (qualidade > 0.5) qualidade -= 0.1; else lado = Math.round(lado * 0.8);
      }
      resolve(resultado);
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("Arquivo de imagem inválido"));
    };
    img.src = url;
  });
}

// Lê a imagem escolhida num <input type="file"> e entrega já reduzida
async function tratarArquivoImagem(e, aoCarregar) {
  const file = e.target.files?.[0];
  e.target.value = "";
  if (!file) return;
  try {
    aoCarregar(await lerImagemComprimida(file));
  } catch {
    alert("Não foi possível abrir esta imagem. Tente outra foto.");
  }
}

// No Firestore, cada imagem vira um documento próprio (limite de 1 MB por
// documento) e o laudo guarda só a referência "img:<id>".
const PREFIXO_IMG = "img:";
const cacheImagens = new Map(); // id -> dataURL (evita baixar de novo)
const imagensJaEnviadas = new Set(); // `${uid}/${id}`

async function idDaImagem(dataUrl) {
  const bytes = new TextEncoder().encode(dataUrl);
  const hash = await crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(hash)).slice(0, 16).map((b) => b.toString(16).padStart(2, "0")).join("");
}

// Troca cada imagem do laudo pela referência e devolve as imagens separadas
async function separarImagens(valor, imagens = new Map()) {
  if (typeof valor === "string") {
    if (!valor.startsWith("data:image/")) return valor;
    const id = await idDaImagem(valor);
    imagens.set(id, valor);
    cacheImagens.set(id, valor);
    return PREFIXO_IMG + id;
  }
  if (Array.isArray(valor)) return Promise.all(valor.map((v) => separarImagens(v, imagens)));
  if (valor && typeof valor === "object") {
    const saida = {};
    for (const [k, v] of Object.entries(valor)) saida[k] = await separarImagens(v, imagens);
    return saida;
  }
  return valor;
}

// Caminho inverso: troca as referências pelas imagens (baixa as que faltarem)
async function restaurarImagens(valor, uidDono) {
  if (typeof valor === "string") {
    if (!valor.startsWith(PREFIXO_IMG)) return valor;
    const id = valor.slice(PREFIXO_IMG.length);
    if (cacheImagens.has(id)) return cacheImagens.get(id);
    try {
      const snap = await getDoc(doc(db, "users", uidDono, "imagens", id));
      const data = snap.exists() ? snap.data().data : null;
      if (data) cacheImagens.set(id, data);
      return data;
    } catch {
      return null; // imagem indisponível: o laudo abre sem ela
    }
  }
  if (Array.isArray(valor)) return Promise.all(valor.map((v) => restaurarImagens(v, uidDono)));
  if (valor && typeof valor === "object") {
    const saida = {};
    for (const [k, v] of Object.entries(valor)) saida[k] = await restaurarImagens(v, uidDono);
    return saida;
  }
  return valor;
}

// Envia as imagens novas e devolve o laudo só com referências
async function prepararLaudoParaNuvem(uid, laudo) {
  const imagens = new Map();
  const dados = await separarImagens(laudo, imagens);
  const envios = [];
  for (const [id, data] of imagens) {
    const chave = `${uid}/${id}`;
    if (imagensJaEnviadas.has(chave)) continue;
    imagensJaEnviadas.add(chave);
    envios.push(
      setDoc(doc(db, "users", uid, "imagens", id), { data, criadoEm: Date.now() })
        .catch((erro) => { imagensJaEnviadas.delete(chave); throw erro; })
    );
  }
  return { dados, envios };
}

// Sem internet, o Firestore guarda no aparelho e envia sozinho quando a conexão
// voltar — por isso esperamos no máximo 4 s pelo servidor. Erros de permissão
// aparecem rápido e são repassados.
function aguardarGravacao(promessas) {
  const limite = new Promise((resolve) => setTimeout(resolve, 4000));
  return Promise.race([Promise.all(promessas), limite]);
}

// ── Projetos ─────────────────────────────────────────────────────────────────
// Cada laudo é um projeto em users/{uid}/laudos/{id}, com nome, situação
// ("andamento" ou "gerado") e datas. O profissional pode ter vários ao mesmo tempo.
function refProjeto(uid, projetoId) {
  return doc(db, "users", uid, "laudos", projetoId);
}

// Resumo mostrado na lista de projetos (não precisa baixar as imagens)
function resumoProjeto(id, dados) {
  const laudo = dados?.laudo || {};
  const empresa = laudo.dadosGerais?.empresa?.razaoSocial || "";
  return {
    id,
    nome: dados?.nome || empresa || "Laudo em andamento",
    status: dados?.status || "andamento",
    criadoEm: dados?.criadoEm || dados?.atualizadoEm || 0,
    atualizadoEm: dados?.atualizadoEm || 0,
    geradoEm: dados?.geradoEm || null,
    empresa,
    cargos: Array.isArray(laudo.cargos) ? laudo.cargos.length : 0,
  };
}

// Grava o conteúdo do projeto aberto (mantém nome e situação)
// Projetos já excluídos: um salvamento automático atrasado não pode recriá-los
const projetosExcluidos = new Set();

async function salvarLaudoNaNuvem(uid, projetoId, laudo) {
  if (!uid || !projetoId || projetosExcluidos.has(projetoId)) return;
  const { dados, envios } = await prepararLaudoParaNuvem(uid, laudo);
  if (projetosExcluidos.has(projetoId)) return;
  envios.push(setDoc(refProjeto(uid, projetoId), { laudo: dados, atualizadoEm: Date.now() }, { merge: true }));
  await aguardarGravacao(envios);
}

// ── Hook de salvamento com feedback ──────────────────────────────────────────
// Os botões "Salvar" das seções usam a função registrada pelo AppLaudo.
const salvamentoAtual = { salvar: null };

function useSalvarSecao() {
  const [status, setStatus] = useState("idle"); // idle | salvando | salvo | erro

  const salvar = async (onDepois) => {
    setStatus("salvando");
    try {
      await salvamentoAtual.salvar?.();
      setStatus("salvo");
      setTimeout(() => {
        setStatus("idle");
        onDepois?.();
      }, 1200);
    } catch {
      // NÃO fingir que salvou - mostrar erro e manter o usuário na tela
      setStatus("erro");
      setTimeout(() => setStatus("idle"), 4000);
    }
  };

  return { status, salvar };
}

// Quadro amarelo com a lista de campos recomendados que faltam
function AvisoCamposFaltando({ faltando }) {
  return (
    <div role="alert" style={{
      background: "#FBF3DC", border: "1px solid #E0B84B",
      borderRadius: 8, padding: "8px 12px",
      fontSize: 12, color: "#7A5C00", lineHeight: 1.5,
      maxHeight: 200, overflowY: "auto",
    }}>
      <strong>Campos recomendados não preenchidos:</strong>
      <ul style={{ margin: "4px 0 0 14px", padding: 0 }}>
        {faltando.map((item, i) => <li key={i}>{item}</li>)}
      </ul>
      <span style={{ display: "block", marginTop: 4 }}>
        Preencha os campos ou toque em "Salvar mesmo assim".
      </span>
    </div>
  );
}

// Botão de salvar das seções. Se faltar algum campo recomendado, o primeiro
// toque só mostra o aviso; o segundo toque ("Salvar mesmo assim") salva.
function BotaoSalvar({ status, onClick, label = "Salvar e voltar", faltando = [] }) {
  const [avisoVisivel, setAvisoVisivel] = useState(false);
  const temPendencias = faltando.length > 0;
  const confirmarSemCampos = avisoVisivel && temPendencias;

  const cor = status === "salvo" ? "#2E7D4F"
    : status === "erro" ? "#C0392B"
    : confirmarSemCampos ? "#B8860B"
    : "#0A2647";

  const texto = status === "salvando" ? "Salvando..."
    : status === "salvo" ? "✓ Salvo!"
    : status === "erro" ? "Não foi possível salvar"
    : confirmarSemCampos ? "Salvar mesmo assim"
    : label;

  const handleClick = () => {
    if (temPendencias && !avisoVisivel) {
      setAvisoVisivel(true);
      return;
    }
    onClick();
  };

  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 6 }}>
      {confirmarSemCampos && status !== "salvo" && <AvisoCamposFaltando faltando={faltando} />}
      <button
        onClick={handleClick}
        disabled={status === "salvando"}
        style={{
          background: cor, color: "#fff",
          border: "none", borderRadius: 12, padding: "15px",
          fontSize: 15, fontWeight: 700, fontFamily: "Inter, sans-serif",
          cursor: status === "salvando" ? "not-allowed" : "pointer",
          boxShadow: `0 4px 12px ${cor}44`,
          transition: "background 0.2s",
          display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
        }}
      >
        {texto}
      </button>
    </div>
  );
}

// ── Validação de campos por seção ────────────────────────────────────────────
function validarDadosGerais(dados) {
  if (!dados) return ["Dados gerais não carregados"];
  const faltando = [];
  if (!dados.empresa?.razaoSocial?.trim()) faltando.push("Razão Social da empresa");
  if (!dados.empresa?.cnpj?.trim()) faltando.push("CNPJ da empresa");
  if (!dados.contrato?.identificacao?.trim()) faltando.push("Identificação do contrato");
  if (!dados.contrato?.contratante?.trim()) faltando.push("Contratante");
  if (!dados.responsavel?.nome?.trim()) faltando.push("Nome do responsável técnico");
  if (!dados.responsavel?.crefito?.trim()) faltando.push("CREFITO do responsável técnico");
  return faltando;
}

function validarPopulacao(dados) {
  if (!dados) return ["Dados de população não carregados"];
  const faltando = [];
  const total = Number(dados.totalMasculino || 0) + Number(dados.totalFeminino || 0);
  if (total === 0) faltando.push("Total de trabalhadores (masculino ou feminino)");
  if (!(dados.escolaridade || []).some((e) => Number(e.valor) > 0)) faltando.push("Dados de escolaridade");
  if (!(dados.queixas || []).some((e) => Number(e.valor) > 0)) faltando.push("Dados de queixas musculoesqueléticas");
  return faltando;
}

function validarPlanoAcao(dados) {
  if (!dados) return ["Dados de plano de ação não carregados"];
  const faltando = [];
  if (!dados.acoes?.length) faltando.push("Pelo menos uma ação no plano");
  if (!dados.consideracoes?.trim()) faltando.push("Considerações finais");
  return faltando;
}

function validarAnexos(dados) {
  if (!dados) return ["Dados de anexos não carregados"];
  const faltando = [];
  if (!dados.certificado) faltando.push("Certificado de capacitação do responsável técnico (Anexo 4)");
  return faltando;
}

function validarCargo(cargo) {
  const faltando = [];
  if (!cargo?.nome?.trim()) faltando.push("Nome do cargo");
  if (!cargo?.condicoes?.descricaoFuncao?.trim()) faltando.push("Descrição das funções");
  if (!cargo?.condicoes?.jornada?.trim()) faltando.push("Jornada de trabalho");
  const temRisco = Object.values(cargo?.riscos || {}).some(v => v?.trim())
    || (cargo?.fmea || []).some((r) => r.fator?.trim());
  if (!temRisco) faltando.push("Pelo menos um risco ergonômico identificado");
  if (!cargo?.rula?.finalD && !cargo?.rula?.finalE) faltando.push("Resultado final do RULA");
  if (!cargo?.conclusao?.trim()) faltando.push("Conclusão do cargo");
  return faltando;
}

