  const setEmpresa = (key, value) =>
    setDados((d) => ({ ...d, empresa: { ...d.empresa, [key]: value } }));
  const setContrato = (key, value) =>
    setDados((d) => ({ ...d, contrato: { ...d.contrato, [key]: value } }));
  const setResponsavel = (key, value) =>
    setDados((d) => ({ ...d, responsavel: { ...d.responsavel, [key]: value } }));
  const setTexto = (key, value) =>
    setDados((d) => ({ ...d, textos: { ...d.textos, [key]: value } }));
  const setCapa = (key, value) =>
    setDados((d) => ({ ...d, capa: { ...d.capa, [key]: value } }));

  // Datas da coleta: a validade é recalculada enquanto estiver no modo automático
  const setDataColeta = (key, value) =>
    setDados((d) => {
      const capa = { ...d.capa, [key]: value };
      return { ...d, capa: validadeEhAutomatica(capa) ? recalcularValidade(capa) : capa };
    });

  const empresaComplete = dados.empresa && Object.values(dados.empresa).some((v) => v?.trim());
  const contratoComplete = dados.contrato && Object.values(dados.contrato).some((v) => v?.trim());
  const responsavelComplete = dados.responsavel && Object.values(dados.responsavel).some((v) => v?.trim());
  const capaComplete = dados.capa && Object.values(dados.capa).some((v) => v !== null && v !== "");

