// Completa um laudo salvo (ou reaberto do histórico) com os campos que faltarem,
// para que versões antigas dos dados não quebrem as telas.
function normalizarLaudo(salvo) {
  const base = emptyLaudo();
  if (!salvo || typeof salvo !== "object") return base;
  const dg = salvo.dadosGerais || {};
  const textosSalvos = Object.fromEntries(
    Object.entries(dg.textos || {}).filter(([, v]) => typeof v === "string")
  );
  const contratoSalvo = { ...(dg.contrato || {}) };
  if (contratoSalvo["pgrResponsável"] !== undefined && contratoSalvo.pgrResponsavel === undefined) {
    contratoSalvo.pgrResponsavel = contratoSalvo["pgrResponsável"];
  }
  delete contratoSalvo["pgrResponsável"];
  const pop = salvo.populacao || {};
  const plano = salvo.planoAcao || {};
  return {
    ...base,
    ...salvo,
    dadosGerais: {
      ...base.dadosGerais,
      ...dg,
      empresa: { ...base.dadosGerais.empresa, ...(dg.empresa || {}) },
      contrato: { ...base.dadosGerais.contrato, ...contratoSalvo },
      responsavel: { ...base.dadosGerais.responsavel, ...(dg.responsavel || {}) },
      textos: { ...base.dadosGerais.textos, ...textosSalvos },
      capa: { ...base.dadosGerais.capa, ...(dg.capa || {}) },
    },
    populacao: {
      ...base.populacao,
      ...pop,
      transporteCargas: { ...base.populacao.transporteCargas, ...(pop.transporteCargas || {}) },
      micropausas: { ...base.populacao.micropausas, ...(pop.micropausas || {}) },
      autonomia: { ...base.populacao.autonomia, ...(pop.autonomia || {}) },
      comunicacao: { ...base.populacao.comunicacao, ...(pop.comunicacao || {}) },
    },
    cargos: Array.isArray(salvo.cargos) ? salvo.cargos : [],
    planoAcao: {
      acoes: Array.isArray(plano.acoes) ? plano.acoes : [],
      consideracoes: typeof plano.consideracoes === "string" && plano.consideracoes.trim()
        ? plano.consideracoes
        : TEXTO_CONSIDERACOES,
    },
    anexos: { ...base.anexos, ...(salvo.anexos || {}) },
  };
}

// Laudo que ficou salvo só no aparelho (versão antiga do app, antes do login).
// No primeiro acesso com conta ele é levado para a nuvem e apagado daqui.
const CHAVE_LAUDO_LOCAL_ANTIGO = "ergolaudo-laudo-atual";
const CHAVES_LOCAIS_ANTIGAS = [
  CHAVE_LAUDO_LOCAL_ANTIGO, "ergolaudo-perfil", "ergolaudo-registros-gerados", "cargos-personalizados",
  "ergolaudo-dados-gerais", "ergolaudo-populacao", "ergolaudo-plano-acao", "ergolaudo-anexos",
];

function lerLocalAntigo(chave) {
  try {
    const bruto = localStorage.getItem(chave);
    return bruto ? JSON.parse(bruto) : null;
  } catch {
    return null;
  }
}

function limparDadosLocaisAntigos() {
  try { CHAVES_LOCAIS_ANTIGAS.forEach((k) => localStorage.removeItem(k)); } catch {}
}

// Um laudo tem conteúdo de verdade (não é só o modelo vazio)?
function laudoTemConteudo(laudo) {
  if (!laudo || typeof laudo !== "object") return false;
  return JSON.stringify(normalizarLaudo(laudo)) !== JSON.stringify(emptyLaudo());
}

// Laudo que ficou só no aparelho, em qualquer versão antiga do app:
// - versão sem login: o laudo inteiro numa chave;
// - primeira versão: cada seção salva separadamente pelos botões "Salvar".
function lerLaudoLegado() {
  const inteiro = lerLocalAntigo(CHAVE_LAUDO_LOCAL_ANTIGO)?.laudo;
  if (laudoTemConteudo(inteiro)) return inteiro;
  const secao = (chave) => lerLocalAntigo(chave)?.dados || null;
  const montado = {};
  const dg = secao("ergolaudo-dados-gerais");
  const pop = secao("ergolaudo-populacao");
  const plano = secao("ergolaudo-plano-acao");
  const anexos = secao("ergolaudo-anexos");
  if (dg) montado.dadosGerais = dg;
  if (pop) montado.populacao = pop;
  if (plano) montado.planoAcao = plano;
  if (anexos) montado.anexos = anexos;
  return laudoTemConteudo(montado) ? montado : null;
}

// Evita levar os mesmos dados duas vezes para a nuvem na mesma sessão
const migracoesFeitas = new Set();

// Leva para a conta tudo o que estava só no aparelho: laudo em andamento e
// histórico de laudos gerados. Só apaga do aparelho depois de gravar na nuvem.
async function migrarDadosDoAparelho(uid, email, nomeProfissional) {
  if (migracoesFeitas.has(uid)) return { projeto: null, registros: [] };
  migracoesFeitas.add(uid);
  try {
    const envios = [];
    let projeto = null;
    const registros = [];

    const laudoAntigo = lerLaudoLegado();
    if (laudoAntigo) {
      const laudoNormal = normalizarLaudo(laudoAntigo);
      const preparado = await prepararLaudoParaNuvem(uid, laudoNormal);
      // Identificação fixa: se a migração for repetida, sobrescreve em vez de duplicar
      const ref = doc(db, "users", uid, "laudos", "aparelho-" + await idDaImagem(JSON.stringify(laudoAntigo)));
      const agora = Date.now();
      const conteudo = {
        nome: laudoNormal.dadosGerais.empresa.razaoSocial || "Laudo recuperado do aparelho",
        status: "andamento", criadoEm: agora, atualizadoEm: agora, laudo: preparado.dados, recuperadoDoAparelho: true,
      };
      envios.push(...preparado.envios, setDoc(ref, conteudo));
      projeto = resumoProjeto(ref.id, conteudo);
    }

    const historicoAntigo = lerLocalAntigo("ergolaudo-registros-gerados");
    if (Array.isArray(historicoAntigo)) {
      for (const r of historicoAntigo) {
        if (!r || typeof r !== "object") continue;
        const preparado = await prepararLaudoParaNuvem(uid, normalizarLaudo(r.laudoSnapshot || {}));
        const ref = doc(db, "registros", "aparelho-" + await idDaImagem(uid + JSON.stringify(r)));
        const registro = {
          uid,
          empresaNome: r.empresaNome || "Empresa sem nome",
          profissionalNome: r.profissionalNome || nomeProfissional || "",
          profissionalEmail: email,
          data: r.data || new Date().toISOString(),
          valorCobrado: r.valorCobrado || "",
          laudoSnapshot: preparado.dados,
          recuperadoDoAparelho: true,
        };
        envios.push(...preparado.envios, setDoc(ref, registro));
        registros.push({ ...registro, id: ref.id });
      }
    }

    await aguardarGravacao(envios);
    limparDadosLocaisAntigos();
    return { projeto, registros };
  } catch (erro) {
    migracoesFeitas.delete(uid); // tenta de novo no próximo acesso; nada foi apagado do aparelho
    throw erro;
  }
}

