function TelaLogin({ cor = "#0A2647" }) {
  const [modo, setModo] = useState("entrar"); // entrar | criar | recuperar
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const [senha, setSenha] = useState("");
  const [erro, setErro] = useState("");
  const [aviso, setAviso] = useState("");
  const [enviando, setEnviando] = useState(false);
  const [aceitou, setAceitou] = useState(false);
  const [docAberto, setDocAberto] = useState(null);
  const [verSenha, setVerSenha] = useState(false);
  const [manterConectado, setManterConectado] = useState(true);

  const trocarModo = (novo) => { setModo(novo); setErro(""); setAviso(""); };

  const enviar = async (e) => {
    e.preventDefault();
    setErro(""); setAviso("");
    const emailLimpo = email.trim();
    if (!emailLimpo) return setErro("Informe o e-mail.");
    if (modo !== "recuperar" && !senha) return setErro("Informe a senha.");
    if (modo === "criar" && !nome.trim()) return setErro("Informe seu nome completo.");
    if (modo === "criar" && !aceitou) return setErro("Para criar a conta, aceite os Termos de Uso e a Política de Privacidade.");
    setEnviando(true);
    try {
      if (modo !== "recuperar") {
        // Conectado neste aparelho até sair, ou só enquanto o navegador estiver aberto
        await setPersistence(auth, manterConectado ? browserLocalPersistence : browserSessionPersistence);
      }
      if (modo === "entrar") {
        await signInWithEmailAndPassword(auth, emailLimpo, senha);
      } else if (modo === "criar") {
        const aceiteTermos = { versao: TERMOS_VERSAO, em: new Date().toISOString() };
        cadastroPendente.atual = { email: emailLimpo.toLowerCase(), nome: nome.trim(), aceiteTermos };
        const cred = await createUserWithEmailAndPassword(auth, emailLimpo, senha);
        await setDoc(doc(db, "users", cred.user.uid), {
          nome: nome.trim(), email: emailLimpo, crefito: "", cargosPersonalizados: [], criadoEm: Date.now(), aceiteTermos,
        }, { merge: true });
      } else {
        await sendPasswordResetEmail(auth, emailLimpo);
        setAviso(`Enviamos um link para ${emailLimpo}. Abra o e-mail (confira também a caixa de spam), crie a nova senha e depois volte aqui para entrar.`);
      }
    } catch (err) {
      setErro(mensagemErroFirebase(err));
    } finally {
      setEnviando(false);
    }
  };

  const campo = {
    width: "100%", fontFamily: "Inter, sans-serif", fontSize: 15.5,
    padding: "13px 14px", border: "1.5px solid #E0DDD6", borderRadius: 10,
    background: "#FAFAF8", color: "#1C1F1D", marginTop: 6, boxSizing: "border-box",
  };
  const rotulo = { display: "block", fontSize: 13, fontWeight: 600, color: "#44473F", marginBottom: 14 };
  const titulo = modo === "entrar" ? "Entrar" : modo === "criar" ? "Criar conta" : "Recuperar senha";

  return (
    <div style={{
      minHeight: "100vh",
      background: `linear-gradient(170deg, ${cor} 0%, ${cor}E8 60%, #1A3A5C 100%)`,
      fontFamily: "Inter, sans-serif", display: "flex", alignItems: "center", justifyContent: "center",
      padding: "32px 16px",
    }}>
      <form onSubmit={enviar} style={{
        width: "100%", maxWidth: 380, background: "#fff", borderRadius: 18,
        padding: "26px 22px", boxShadow: "0 20px 60px rgba(0,0,0,0.25)",
      }}>
        <img src={LOGO_ERGOLAUDO} alt="ErgoLaudo" style={{ display: "block", width: 140, margin: "0 auto 14px" }} />
        <h1 style={{ fontFamily: "Sora, sans-serif", fontSize: 21, margin: "0 0 18px", textAlign: "center", color: "#1C1F1D" }}>
          {titulo}
        </h1>

        {modo === "criar" && (
          <label style={rotulo}>Nome completo
            <input style={campo} value={nome} onChange={(e) => setNome(e.target.value)} autoComplete="name" placeholder="Ex.: Rafael Henrique Souza" />
          </label>
        )}
        <label style={rotulo}>E-mail
          <input style={campo} type="email" value={email} onChange={(e) => setEmail(e.target.value)} autoComplete="email" inputMode="email" placeholder="seu@email.com" />
        </label>
        {modo !== "recuperar" && (
          <label style={rotulo}>Senha
            <span style={{ position: "relative", display: "block" }}>
              <input style={{ ...campo, paddingRight: 46 }} type={verSenha ? "text" : "password"} value={senha} onChange={(e) => setSenha(e.target.value)}
                autoComplete={modo === "criar" ? "new-password" : "current-password"}
                placeholder={modo === "criar" ? "Mínimo de 6 caracteres" : "Sua senha"} />
              <button type="button" onClick={() => setVerSenha((v) => !v)}
                aria-label={verSenha ? "Esconder senha" : "Mostrar senha"} title={verSenha ? "Esconder senha" : "Mostrar senha"}
                style={{ position: "absolute", right: 6, top: "50%", transform: "translateY(-50%)", marginTop: 3, background: "none", border: "none", padding: 8, cursor: "pointer", color: "#6B6B63", display: "flex" }}>
                {verSenha ? <EyeOff size={19} /> : <Eye size={19} />}
              </button>
            </span>
          </label>
        )}
        {modo !== "recuperar" && (
          <label style={{ display: "flex", alignItems: "center", gap: 10, fontSize: 13, color: "#44473F", margin: "-4px 0 14px", cursor: "pointer" }}>
            <input type="checkbox" checked={manterConectado} onChange={(e) => setManterConectado(e.target.checked)}
              style={{ width: 18, height: 18, flexShrink: 0, accentColor: cor }} />
            Manter conectado neste aparelho
          </label>
        )}
        {modo === "recuperar" && (
          <p style={{ fontSize: 13, color: "#6B6B63", lineHeight: 1.5, margin: "-4px 0 14px" }}>
            Informe o e-mail da sua conta. Você vai receber um link para criar uma nova senha.
          </p>
        )}

        {modo === "criar" && <CaixaAceite marcado={aceitou} onMarcar={setAceitou} onAbrir={setDocAberto} cor={cor} />}

        {erro && <p role="alert" style={{ background: "#FBE8E6", color: "#C0392B", fontSize: 13, borderRadius: 8, padding: "9px 12px", margin: "0 0 12px", lineHeight: 1.45 }}>{erro}</p>}
        {aviso && <p style={{ background: "#E8F5EC", color: "#2E7D4F", fontSize: 13, borderRadius: 8, padding: "9px 12px", margin: "0 0 12px", lineHeight: 1.45 }}>{aviso}</p>}

        <button type="submit" disabled={enviando} style={{
          width: "100%", background: cor, color: "#fff", border: "none", borderRadius: 12,
          padding: 15, fontSize: 15.5, fontWeight: 700, fontFamily: "Inter, sans-serif",
          cursor: enviando ? "wait" : "pointer", opacity: enviando ? 0.75 : 1,
        }}>
          {enviando ? "Aguarde..." : modo === "entrar" ? "Entrar" : modo === "criar" ? "Criar conta" : "Enviar link"}
        </button>

        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 10, marginTop: 16, fontSize: 13.5 }}>
          {modo === "entrar" && (
            <>
              <button type="button" onClick={() => trocarModo("recuperar")} style={linkBtn(cor)}>Esqueci minha senha</button>
              <span style={{ color: "#8A8A82" }}>Não tem conta? <button type="button" onClick={() => trocarModo("criar")} style={linkBtn(cor)}>Criar conta</button></span>
            </>
          )}
          {modo !== "entrar" && (
            <button type="button" onClick={() => trocarModo("entrar")} style={linkBtn(cor)}>← Voltar para entrar</button>
          )}
        </div>

        <div style={{ borderTop: "1px solid #F0EEE6", marginTop: 18, paddingTop: 12, textAlign: "center", fontSize: 11.5, color: "#9B9A90", lineHeight: 1.6 }}>
          <button type="button" onClick={() => setDocAberto("termos")} style={{ ...linkBtn("#8A8A82"), fontSize: 11.5, fontWeight: 600 }}>Termos de Uso</button>
          {" · "}
          <button type="button" onClick={() => setDocAberto("privacidade")} style={{ ...linkBtn("#8A8A82"), fontSize: 11.5, fontWeight: 600 }}>Privacidade</button>
          {" · "}
          <button type="button" onClick={() => setDocAberto("manual")} style={{ ...linkBtn("#8A8A82"), fontSize: 11.5, fontWeight: 600 }}>Manual de uso</button>
          <br />{AVISO_COPYRIGHT}
        </div>
      </form>
      {docAberto && <DocumentoLegal tipo={docAberto} onFechar={() => setDocAberto(null)} cor={cor} />}
    </div>
  );
}

function linkBtn(cor) {
  return {
    background: "none", border: "none", padding: 0, color: cor, fontWeight: 700,
    fontSize: 13.5, cursor: "pointer", fontFamily: "Inter, sans-serif", textDecoration: "underline",
  };
}

// ==================== Meus Projetos ====================
function formatarDataHora(ms) {
  if (!ms) return "";
  const d = new Date(ms);
  return `${d.toLocaleDateString("pt-BR")} às ${d.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}`;
}

// Janela para dar nome a um projeto (novo ou renomear)
function ModalNomeProjeto({ titulo, textoBotao, nomeInicial = "", onConfirmar, onCancelar, cor = "#0A2647" }) {
  const [nome, setNome] = useState(nomeInicial);
  const [enviando, setEnviando] = useState(false);
  const confirmar = async (e) => {
    e.preventDefault();
    if (!nome.trim() || enviando) return;
    setEnviando(true);
    try { await onConfirmar(nome.trim()); } finally { setEnviando(false); }
  };
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(28,31,29,0.5)", zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center", padding: 20, fontFamily: "Inter, sans-serif" }}>
      <form onSubmit={confirmar} style={{ background: "#F7F8FA", borderRadius: 14, padding: 22, width: "100%", maxWidth: 380 }}>
        <h2 style={{ fontSize: 18, fontWeight: 700, color: "#1C1F1D", margin: "0 0 6px" }}>{titulo}</h2>
        <p style={{ fontSize: 13, color: "#8A8A82", margin: "0 0 14px", lineHeight: 1.5 }}>
          Use um nome fácil de reconhecer, como o nome da empresa ou da obra.
        </p>
        <input autoFocus value={nome} onChange={(e) => setNome(e.target.value)} maxLength={80}
          placeholder="Ex.: AET Construtora Silva — 2026"
          style={{ width: "100%", boxSizing: "border-box", fontFamily: "Inter, sans-serif", fontSize: 15, padding: "12px 13px", border: "1.5px solid #D8D6CD", borderRadius: 9, background: "#fff", marginBottom: 16 }} />
        <div style={{ display: "flex", gap: 10 }}>
          <button type="button" onClick={onCancelar} style={{ flex: 1, background: "#fff", border: "1px solid #D8D6CD", borderRadius: 9, padding: 12, fontSize: 14.5, fontWeight: 600, color: "#44473F", cursor: "pointer" }}>
            Cancelar
          </button>
          <button type="submit" disabled={!nome.trim() || enviando} style={{ flex: 1, background: cor, border: "none", borderRadius: 9, padding: 12, fontSize: 14.5, fontWeight: 700, color: "#fff", cursor: nome.trim() ? "pointer" : "not-allowed", opacity: nome.trim() ? 1 : 0.5 }}>
            {enviando ? "Salvando..." : textoBotao}
          </button>
        </div>
      </form>
    </div>
  );
}

function TelaProjetos({
  projetos, cor, escuro, aviso, abrindoId,
  onNovo, onAbrir, onRenomear, onExcluir, onDuplicar,
  onAbrirHistorico, registrosCount = 0, nomeProfissional, onAbrirPerfil,
}) {
  const [modal, setModal] = useState(null); // { tipo: "novo" } | { tipo: "renomear", projeto }
  const fundo = escuro ? "#0F1117" : "#F7F8FA";
  const cartao = escuro ? "#1C2030" : "#fff";
  const borda = escuro ? "#2A2D3A" : "#E8E6DF";
  const texto = escuro ? "#F0EEE6" : "#1C1F1D";
  const suave = escuro ? "#6B7280" : "#8A8A82";

  const emAndamento = projetos.filter((p) => p.status !== "gerado").sort((a, b) => b.atualizadoEm - a.atualizadoEm);
  const gerados = projetos.filter((p) => p.status === "gerado").sort((a, b) => b.atualizadoEm - a.atualizadoEm);

  const botaoAcao = { background: "none", border: "none", padding: "6px 4px", fontSize: 12.5, fontWeight: 600, cursor: "pointer", fontFamily: "Inter, sans-serif" };

  const Lista = ({ titulo, itens }) => itens.length === 0 ? null : (
    <>
      <p style={{ fontFamily: "Sora, sans-serif", fontSize: 10.5, fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase", color: suave, margin: "22px 0 8px 4px" }}>
        {titulo} ({itens.length})
      </p>
      {itens.map((pj) => (
        <div key={pj.id} style={{ background: cartao, border: `1px solid ${borda}`, borderRadius: 14, marginBottom: 10, overflow: "hidden", boxShadow: escuro ? "none" : "0 1px 4px rgba(0,0,0,0.05)" }}>
          <button onClick={() => onAbrir(pj.id)} disabled={!!abrindoId} style={{
            width: "100%", display: "flex", alignItems: "center", gap: 12, padding: "15px 16px",
            background: "none", border: "none", cursor: abrindoId ? "wait" : "pointer", textAlign: "left", fontFamily: "Inter, sans-serif",
          }}>
            <span style={{ width: 40, height: 40, borderRadius: 10, background: `${cor}18`, color: cor, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
              <Folder size={20} />
            </span>
            <span style={{ flex: 1, minWidth: 0 }}>
              <span style={{ display: "block", fontSize: 15, fontWeight: 700, color: texto, overflowWrap: "anywhere" }}>{pj.nome}</span>
              <span style={{ display: "block", fontSize: 12, color: suave, marginTop: 2 }}>
                {pj.empresa && pj.empresa !== pj.nome ? `${pj.empresa} · ` : ""}{pj.cargos} cargo{pj.cargos === 1 ? "" : "s"}
              </span>
              <span style={{ display: "block", fontSize: 11.5, color: suave, marginTop: 2 }}>
                {abrindoId === pj.id ? "Abrindo..." : `Salvo em ${formatarDataHora(pj.atualizadoEm)}`}
              </span>
            </span>
            <span style={{
              fontSize: 10.5, fontWeight: 700, borderRadius: 20, padding: "3px 9px", flexShrink: 0,
              background: pj.status === "gerado" ? "#E8F5EC" : "#FBF3DC",
              color: pj.status === "gerado" ? "#2E7D4F" : "#7A5C00",
            }}>
              {pj.status === "gerado" ? "PDF gerado" : "Em andamento"}
            </span>
          </button>
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 14, padding: "0 14px 8px", borderTop: `1px solid ${borda}` }}>
            <button onClick={() => setModal({ tipo: "duplicar", projeto: pj })} style={{ ...botaoAcao, color: suave }}>Duplicar</button>
            <button onClick={() => setModal({ tipo: "renomear", projeto: pj })} style={{ ...botaoAcao, color: suave }}>Renomear</button>
            <button onClick={() => onExcluir(pj.id, pj.nome)} style={{ ...botaoAcao, color: "#C0392B" }}>Excluir</button>
          </div>
        </div>
      ))}
    </>
  );

  return (
    <div style={{ minHeight: "100vh", background: fundo, fontFamily: "Inter, sans-serif", color: texto, paddingBottom: 110 }}>
      <div style={{ background: cor, color: "#F7F8FA", padding: "22px 20px 24px" }}>
        <div style={{ maxWidth: 640, margin: "0 auto" }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 6 }}>
            <p style={{ fontFamily: "Sora, sans-serif", fontSize: 11, letterSpacing: "0.08em", textTransform: "uppercase", opacity: 0.7, margin: 0 }}>ErgoLaudo · AET</p>
            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
              <button className="historico-btn" onClick={onAbrirHistorico} aria-label="Ver histórico de laudos gerados"
                style={{ position: "relative", background: "none", border: "none", color: "#F7F8FA", display: "flex", padding: 4, cursor: "pointer" }}>
                <Bell size={19} />
                {registrosCount > 0 && <span className="historico-dot" style={{ position: "absolute", top: 2, right: 2, width: 9, height: 9, borderRadius: "50%", background: "#E0954F", border: `1.5px solid ${cor}` }} />}
              </button>
              <button onClick={onAbrirPerfil} aria-label="Configurações" title={nomeProfissional || "Configure seu perfil"} style={{
                width: 34, height: 34, borderRadius: "50%", background: nomeProfissional ? "#E0954F" : "rgba(255,255,255,0.15)",
                border: nomeProfissional ? "none" : "1.5px dashed rgba(255,255,255,0.5)", color: "#fff",
                fontFamily: "Sora, sans-serif", fontWeight: 700, fontSize: 13, cursor: "pointer",
              }}>
                {nomeProfissional ? nomeProfissional.split(" ").filter(Boolean).slice(0, 2).map((n) => n[0]).join("").toUpperCase() : "?"}
              </button>
            </div>
          </div>
          <h1 style={{ fontSize: 24, fontWeight: 700, margin: "0 0 4px" }}>Meus Projetos</h1>
          <p style={{ fontSize: 13, opacity: 0.85, margin: 0 }}>
            {emAndamento.length} em andamento · {gerados.length} com PDF gerado
          </p>
        </div>
      </div>

      <div style={{ maxWidth: 640, margin: "0 auto", padding: 16 }}>
        {aviso && (
          <div role="status" style={{ background: "#E8F5EC", border: "1px solid #2E7D4F", color: "#1E5A37", borderRadius: 10, padding: "10px 12px", fontSize: 13, lineHeight: 1.5, marginBottom: 12 }}>
            {aviso}
          </div>
        )}
        <button onClick={() => setModal({ tipo: "novo" })} style={{
          width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
          background: cor, color: "#fff", border: "none", borderRadius: 12, padding: 15,
          fontSize: 15, fontWeight: 700, fontFamily: "Inter, sans-serif", cursor: "pointer", boxShadow: `0 4px 12px ${cor}44`,
        }}>
          <Plus size={18} /> Novo projeto
        </button>

        {projetos.length === 0 ? (
          <div style={{ textAlign: "center", padding: "50px 20px", color: suave }}>
            <FolderOpen size={36} style={{ opacity: 0.5, marginBottom: 10 }} />
            <p style={{ fontSize: 14, margin: 0, lineHeight: 1.6 }}>
              Nenhum projeto ainda.<br />Toque em "Novo projeto", dê um nome e comece o laudo.<br />Você pode ter vários projetos ao mesmo tempo.
            </p>
          </div>
        ) : (
          <>
            <Lista titulo="Em andamento" itens={emAndamento} />
            <Lista titulo="PDF gerado — salvos para correção" itens={gerados} />
          </>
        )}
      </div>

      {modal?.tipo === "novo" && (
        <ModalNomeProjeto titulo="Novo projeto" textoBotao="Criar e começar" cor={cor}
          onCancelar={() => setModal(null)}
          onConfirmar={async (nome) => { await onNovo(nome); setModal(null); }} />
      )}
      {modal?.tipo === "duplicar" && (
        <ModalNomeProjeto titulo="Duplicar projeto" textoBotao="Criar cópia" cor={cor} nomeInicial={`Cópia de ${modal.projeto.nome}`}
          onCancelar={() => setModal(null)}
          onConfirmar={async (nome) => { await onDuplicar(modal.projeto.id, nome); setModal(null); }} />
      )}
      {modal?.tipo === "renomear" && (
        <ModalNomeProjeto titulo="Renomear projeto" textoBotao="Salvar nome" cor={cor} nomeInicial={modal.projeto.nome}
          onCancelar={() => setModal(null)}
          onConfirmar={async (nome) => { await onRenomear(modal.projeto.id, nome); setModal(null); }} />
      )}
    </div>
  );
}

// ---------- Blocos visuais da tela de Configurações ----------
// Ficam fora do AppLaudo: se forem criados dentro dele, o React recria os campos
// a cada letra digitada e o input perde o foco.
function ConfigSectionLabel({ escuro, children }) {
  return (
    <p style={{
      fontFamily: "Sora, sans-serif", fontSize: 10.5, fontWeight: 700,
      letterSpacing: "0.08em", textTransform: "uppercase",
      color: escuro ? "#6B7280" : "#9B9A90", margin: "24px 0 8px 4px",
    }}>{children}</p>
  );
}

function ConfigCard({ cardBg, borda, escuro, style = {}, children }) {
  return (
    <div style={{
      background: cardBg,
      border: `1px solid ${borda}`,
      borderRadius: 14,
      overflow: "hidden",
      boxShadow: escuro ? "none" : "0 1px 3px rgba(0,0,0,0.06)",
      ...style,
    }}>{children}</div>
  );
}

function AppLaudo() {
  const [showSplash, setShowSplash] = useState(true);
  const [usuario, setUsuario] = useState(undefined); // undefined = verificando | null = sem login
  const [dadosProntos, setDadosProntos] = useState(false);
  const [erroCarregamento, setErroCarregamento] = useState("");
  const [tentativaCarga, setTentativaCarga] = useState(0);
  const [isAdmin, setIsAdmin] = useState(false);
  const [laudo, setLaudo] = useState(emptyLaudo);
  const [perfil, setPerfil] = useState({ nome: "", email: "", crefito: "", cargosPersonalizados: [] });
  const [perfilStatus, setPerfilStatus] = useState("idle"); // idle | salvando | salvo | erro
  const [registros, setRegistros] = useState([]);
  const [tela, setTela] = useState("projetos");
  const [projetos, setProjetos] = useState([]); // resumo de cada projeto (sem imagens)
  const [projetoAtualId, setProjetoAtualId] = useState(null);
  const [abrindoId, setAbrindoId] = useState(null);
  const [aviso, setAviso] = useState("");
  const [abaAtiva, setAbaAtiva] = useState("laudo"); // "laudo" | "gerados" | "config"
  const [tema, setTema] = useState(() => lerLocalAntigo("ergolaudo-tema") || { cor: "#0A2647", modoEscuro: false });
  const [cargoAbertoId, setCargoAbertoId] = useState(null);
  const [mostrarModalGeracao, setMostrarModalGeracao] = useState(false);
  const [docLegalAberto, setDocLegalAberto] = useState(null); // "termos" | "privacidade" | null
  const avisouErroNuvem = useRef(false);
  const uid = usuario?.uid;

  // ---------- Login ----------
  useEffect(() => {
    if (!auth) return undefined;
    return onAuthStateChanged(auth, (u) => setUsuario(u || null));
  }, []);

  // ---------- Carrega perfil, laudo em andamento e histórico da conta ----------
  useEffect(() => {
    if (!usuario) {
      setDadosProntos(false);
      return undefined;
    }
    let cancelado = false;
    (async () => {
      setErroCarregamento("");
      try {
        const [snapPerfil, snapAdmin, snapProjetos] = await Promise.all([
          getDoc(doc(db, "users", usuario.uid)),
          getDoc(doc(db, "admins", usuario.uid)).catch(() => null),
          getDocs(collection(db, "users", usuario.uid, "laudos")),
        ]);
        const admin = !!snapAdmin?.exists();

        // Perfil (no primeiro acesso, aproveita o que estava salvo no aparelho)
        const p = snapPerfil.exists() ? snapPerfil.data() : {};
        const perfilLocal = lerLocalAntigo("ergolaudo-perfil") || {};
        const cargosLocais = lerLocalAntigo("cargos-personalizados");
        // Cadastro recém-feito neste aparelho (o perfil pode ainda não ter chegado à nuvem)
        const pendente = cadastroPendente.atual?.email === (usuario.email || "").toLowerCase() ? cadastroPendente.atual : null;
        const perfilFinal = {
          nome: p.nome || pendente?.nome || perfilLocal.nome || "",
          crefito: p.crefito || perfilLocal.crefito || "",
          email: usuario.email,
          cargosPersonalizados: Array.isArray(p.cargosPersonalizados) && p.cargosPersonalizados.length
            ? p.cargosPersonalizados
            : Array.isArray(cargosLocais) ? cargosLocais : [],
          ...((p.aceiteTermos || pendente?.aceiteTermos) ? { aceiteTermos: p.aceiteTermos || pendente.aceiteTermos } : {}),
          registrosOcultos: Array.isArray(p.registrosOcultos) ? p.registrosOcultos : [],
        };

        // Projetos da conta (só o resumo; as imagens são baixadas ao abrir)
        const listaProjetos = snapProjetos.docs.map((d) => resumoProjeto(d.id, d.data()));

        // Perfil que estava só no aparelho vai para a conta antes de limpar o aparelho
        const tinhaPerfilLocal = !!(perfilLocal.nome || perfilLocal.crefito || (Array.isArray(cargosLocais) && cargosLocais.length));
        if (tinhaPerfilLocal || !snapPerfil.exists() || p.email !== usuario.email || pendente) {
          await aguardarGravacao([setDoc(doc(db, "users", usuario.uid), perfilFinal, { merge: true })]);
        }

        // Laudo e histórico que estavam só no aparelho (versões antigas do app)
        let avisoMigracao = "";
        try {
          const migrado = await migrarDadosDoAparelho(usuario.uid, usuario.email, perfilFinal.nome);
          if (migrado.projeto) {
            const indice = listaProjetos.findIndex((pj) => pj.id === migrado.projeto.id);
            if (indice >= 0) listaProjetos[indice] = migrado.projeto; else listaProjetos.push(migrado.projeto);
            avisoMigracao = `O laudo que estava salvo só neste aparelho foi levado para a sua conta: "${migrado.projeto.nome}".`;
          }
          if (migrado.registros.length) {
            avisoMigracao += ` ${migrado.registros.length} laudo${migrado.registros.length === 1 ? "" : "s"} do histórico também ${migrado.registros.length === 1 ? "foi levado" : "foram levados"}.`;
          }
        } catch {
          // Os dados antigos continuam guardados no aparelho; nova tentativa no próximo acesso
          avisoMigracao = "Os dados antigos deste aparelho ainda não puderam ir para a nuvem. Eles continuam guardados aqui e o app tenta de novo no próximo acesso.";
        }

        // Histórico: o admin vê todos; os demais, só os próprios
        const consulta = admin
          ? collection(db, "registros")
          : query(collection(db, "registros"), where("uid", "==", usuario.uid));
        const snapReg = await getDocs(consulta);
        const lista = snapReg.docs.map((d) => ({ ...d.data(), id: d.id }));

        if (cancelado) return;
        setIsAdmin(admin);
        setPerfil(perfilFinal);
        setProjetos(listaProjetos);
        setProjetoAtualId(null);
        setLaudo(emptyLaudo());
        setTela("projetos");
        setRegistros(lista);
        setDadosProntos(true);
        if (avisoMigracao) mostrarAviso(avisoMigracao.trim());
        cadastroPendente.atual = null;
      } catch (erro) {
        if (!cancelado) setErroCarregamento(mensagemErroFirebase(erro));
      }
    })();
    return () => { cancelado = true; };
  }, [usuario, tentativaCarga]);

  // ---------- Salvamento automático do projeto aberto (1,5 s após a última alteração) ----------
  useEffect(() => {
    if (!uid || !dadosProntos || !projetoAtualId) return undefined;
    const t = setTimeout(() => {
      salvarLaudoNaNuvem(uid, projetoAtualId, laudo)
        .then(() => {
          avisouErroNuvem.current = false;
          atualizarResumo(projetoAtualId, laudo);
        })
        .catch((erro) => {
          if (!avisouErroNuvem.current) {
            avisouErroNuvem.current = true;
            alert("Não foi possível salvar o laudo na nuvem: " + mensagemErroFirebase(erro));
          }
        });
    }, 1500);
    return () => clearTimeout(t);
  }, [laudo, uid, dadosProntos, projetoAtualId]);

  // Usado pelos botões "Salvar" de cada seção
  salvamentoAtual.salvar = uid && projetoAtualId ? () => salvarLaudoNaNuvem(uid, projetoAtualId, laudo) : null;

  // ---------- Projetos ----------
  const mostrarAviso = (texto) => {
    setAviso(texto);
    setTimeout(() => setAviso((atual) => (atual === texto ? "" : atual)), 6000);
  };

  // Atualiza o resumo da lista depois de salvar
  function atualizarResumo(id, laudoSalvo, extra = {}) {
    setProjetos((lista) => lista.map((pj) => pj.id !== id ? pj : {
      ...pj,
      ...extra,
      atualizadoEm: Date.now(),
      empresa: laudoSalvo?.dadosGerais?.empresa?.razaoSocial || "",
      cargos: laudoSalvo?.cargos?.length || 0,
    }));
  }

  const criarProjeto = async (nome, laudoInicial = emptyLaudo(), dadosProntosParaNuvem = null) => {
    try {
      const ref = doc(collection(db, "users", uid, "laudos"));
      const agora = Date.now();
      const { dados, envios } = dadosProntosParaNuvem
        ? { dados: dadosProntosParaNuvem, envios: [] }
        : await prepararLaudoParaNuvem(uid, laudoInicial);
      const conteudo = { nome, status: "andamento", criadoEm: agora, atualizadoEm: agora, laudo: dados };
      envios.push(setDoc(ref, conteudo));
      await aguardarGravacao(envios);
      setProjetos((lista) => [resumoProjeto(ref.id, conteudo), ...lista]);
      setAviso("");
      setLaudo(normalizarLaudo(laudoInicial));
      setProjetoAtualId(ref.id);
      setAbaAtiva("laudo");
      setTela("menu");
    } catch (erro) {
      alert("Não foi possível criar o projeto: " + mensagemErroFirebase(erro));
    }
  };

  const abrirProjeto = async (id) => {
    setAviso("");
    setAbrindoId(id);
    try {
      const snap = await getDoc(refProjeto(uid, id));
      if (!snap.exists()) throw Object.assign(new Error("não encontrado"), { code: "not-found" });
      const restaurado = await restaurarImagens(snap.data().laudo, uid);
      setLaudo(normalizarLaudo(restaurado));
      setProjetoAtualId(id);
      setTela("menu");
    } catch (erro) {
      alert("Não foi possível abrir o projeto: " + mensagemErroFirebase(erro));
    } finally {
      setAbrindoId(null);
    }
  };

  // "Salvar e sair": grava tudo e volta para a lista de projetos
  const salvarESair = async () => {
    const id = projetoAtualId;
    try {
      await salvarLaudoNaNuvem(uid, id, laudo);
      atualizarResumo(id, laudo);
      const nome = projetos.find((pj) => pj.id === id)?.nome || "Projeto";
      mostrarAviso(`"${nome}" foi salvo. Você pode continuar de onde parou quando quiser.`);
    } catch (erro) {
      alert("Não foi possível salvar o projeto: " + mensagemErroFirebase(erro));
      return; // fica no projeto para não perder nada
    }
    setProjetoAtualId(null);
    setLaudo(emptyLaudo());
    setTela("projetos");
  };

  // Cria uma cópia completa (dados, cargos, fotos) para usar como base de outro laudo
  const duplicarProjeto = async (id, nome) => {
    try {
      if (id === projetoAtualId) await salvarLaudoNaNuvem(uid, id, laudo);
      const snap = await getDoc(refProjeto(uid, id));
      if (!snap.exists()) throw Object.assign(new Error("não encontrado"), { code: "not-found" });
      const ref = doc(collection(db, "users", uid, "laudos"));
      const agora = Date.now();
      const conteudo = { nome, status: "andamento", criadoEm: agora, atualizadoEm: agora, laudo: snap.data().laudo || {}, copiaDe: id };
      await aguardarGravacao([setDoc(ref, conteudo)]);
      setProjetos((lista) => [resumoProjeto(ref.id, conteudo), ...lista]);
      mostrarAviso(`Cópia "${nome}" criada. Ela é independente: alterar uma não muda a outra.`);
    } catch (erro) {
      alert("Não foi possível duplicar: " + mensagemErroFirebase(erro));
    }
  };

  const renomearProjeto = async (id, nome) => {
    try {
      await aguardarGravacao([setDoc(refProjeto(uid, id), { nome }, { merge: true })]);
      setProjetos((lista) => lista.map((pj) => (pj.id === id ? { ...pj, nome } : pj)));
    } catch (erro) {
      alert("Não foi possível renomear: " + mensagemErroFirebase(erro));
    }
  };

  const excluirProjeto = async (id, nome) => {
    if (!window.confirm(`Excluir o projeto "${nome}"? As informações dele serão apagadas. Laudos já gerados continuam no histórico.`)) return;
    try {
      projetosExcluidos.add(id);
      await aguardarGravacao([deleteDoc(refProjeto(uid, id))]);
      setProjetos((lista) => lista.filter((pj) => pj.id !== id));
      if (id === projetoAtualId) { setProjetoAtualId(null); setLaudo(emptyLaudo()); setTela("projetos"); }
      mostrarAviso(`Projeto "${nome}" excluído.`);
    } catch (erro) {
      alert("Não foi possível excluir: " + mensagemErroFirebase(erro));
    }
  };

  const salvarTema = (novoTema) => {
    setTema(novoTema);
    try { localStorage.setItem("ergolaudo-tema", JSON.stringify(novoTema)); } catch {}
  };

  const salvarPerfil = async (novoPerfil) => {
    setPerfil(novoPerfil);
    setPerfilStatus("salvando");
    try {
      const gravacao = setDoc(doc(db, "users", uid), {
        nome: novoPerfil.nome || "",
        crefito: novoPerfil.crefito || "",
        email: usuario.email,
      }, { merge: true });
      await Promise.race([gravacao, new Promise((r) => setTimeout(r, 4000))]);
      setPerfilStatus("salvo");
    } catch (erro) {
      setPerfilStatus("erro");
      alert("Não foi possível salvar o perfil: " + mensagemErroFirebase(erro));
    }
    setTimeout(() => setPerfilStatus("idle"), 2000);
  };

  const alterarCargosSalvos = (lista) => {
    setPerfil((p) => ({ ...p, cargosPersonalizados: lista }));
    setDoc(doc(db, "users", uid), { cargosPersonalizados: lista }, { merge: true })
      .catch((erro) => alert("Não foi possível salvar a lista de cargos: " + mensagemErroFirebase(erro)));
  };

  const aceitarTermos = async () => {
    const aceiteTermos = { versao: TERMOS_VERSAO, em: new Date().toISOString() };
    try {
      await Promise.race([
        setDoc(doc(db, "users", uid), { aceiteTermos }, { merge: true }),
        new Promise((r) => setTimeout(r, 4000)),
      ]);
      setPerfil((p) => ({ ...p, aceiteTermos }));
    } catch (erro) {
      alert("Não foi possível registrar o aceite: " + mensagemErroFirebase(erro));
    }
  };

  const sairDaConta = async () => {
    if (!window.confirm("Sair da conta neste aparelho?")) return;
    try {
      if (projetoAtualId) await salvarLaudoNaNuvem(uid, projetoAtualId, laudo);
    } catch {}
    await signOut(auth);
    setShowSplash(false); // depois de sair, vai direto para a tela de entrar
    cacheImagens.clear();
    imagensJaEnviadas.clear();
    setLaudo(emptyLaudo());
    setRegistros([]);
    setPerfil({ nome: "", email: "", crefito: "", cargosPersonalizados: [] });
    setIsAdmin(false);
    setProjetos([]);
    setProjetoAtualId(null);
    setTela("projetos");
    setAbaAtiva("laudo");
  };

  // Cria um novo projeto a partir de um laudo já gerado (as imagens já estão na nuvem)
  const reabrirRegistro = async (registro) => {
    try {
      const restaurado = await restaurarImagens(registro.laudoSnapshot, registro.uid || uid);
      const mesmoDono = !registro.uid || registro.uid === uid;
      await criarProjeto(`${registro.empresaNome || "Laudo"} (reaberto)`, restaurado, mesmoDono ? registro.laudoSnapshot : null);
    } catch (erro) {
      alert("Não foi possível reabrir este laudo: " + mensagemErroFirebase(erro));
    }
  };

  const usuarioAtual = { nome: perfil.nome, email: usuario?.email || "", isAdmin };
  // Laudos que o profissional excluiu da própria lista continuam no histórico do admin
  const ocultos = new Set(perfil.registrosOcultos || []);
  const meusRegistros = registros.filter((r) => r.uid === uid && !ocultos.has(r.id));

  const excluirRegistroDaLista = (r) => {
    if (!window.confirm(`Excluir o laudo "${r.empresaNome || "sem nome"}" da sua lista? Ele deixa de aparecer para você.`)) return;
    const lista = [...new Set([...(perfil.registrosOcultos || []), r.id])];
    setPerfil((p) => ({ ...p, registrosOcultos: lista }));
    setDoc(doc(db, "users", uid), { registrosOcultos: lista }, { merge: true })
      .catch((erro) => alert("Não foi possível excluir o laudo: " + mensagemErroFirebase(erro)));
  };

  const enviarLinkNovaSenha = async () => {
    const email = usuario?.email;
    if (!email) return;
    if (!window.confirm(`Enviar um link para criar uma nova senha para ${email}?`)) return;
    try {
      await sendPasswordResetEmail(auth, email);
      alert(`Enviamos o link para ${email}. Abra o e-mail (confira também a caixa de spam) e crie a nova senha.`);
    } catch (erro) {
      alert("Não foi possível enviar o link: " + mensagemErroFirebase(erro));
    }
  };

  const irParaMenu = () => setTela("menu");

  // ---------- Section setters (one per top-level slice of `laudo`) ----------

  const setDadosGerais = (updater) =>
    setLaudo((l) => ({
      ...l,
      dadosGerais: typeof updater === "function" ? updater(l.dadosGerais) : updater,
    }));

  const setPopulacao = (updater) =>
    setLaudo((l) => ({
      ...l,
      populacao: typeof updater === "function" ? updater(l.populacao) : updater,
    }));

  const setPlanoAcao = (updater) =>
    setLaudo((l) => ({
      ...l,
      planoAcao: typeof updater === "function" ? updater(l.planoAcao) : updater,
    }));

  const setAnexos = (updater) =>
    setLaudo((l) => ({
      ...l,
      anexos: typeof updater === "function" ? updater(l.anexos) : updater,
    }));

  // ---------- Cargo flow (mirrors the previously-validated App.jsx) ----------

  const handleAdicionarCargoVazio = () => {
    const novo = { id: crypto.randomUUID(), ...emptyCargo(), complete: false };
    setLaudo((l) => ({ ...l, cargos: [novo, ...l.cargos] }));
    setCargoAbertoId(novo.id);
    setTela("cargoForm");
  };

  const handleConfirmarSelecaoCargos = (nomes) => {
    const novos = nomes.map((nome) => ({
      id: crypto.randomUUID(), ...emptyCargo(), nome, complete: false,
    }));
    setLaudo((l) => {
      const nomesExistentes = new Set((l.cargos || []).map((c) => c.nome));
      const semDuplicar = novos.filter((n) => !nomesExistentes.has(n.nome));
      return { ...l, cargos: [...semDuplicar, ...l.cargos] };
    });
  };

  const handleAbrirCargo = (id) => {
    setCargoAbertoId(id);
    setTela("cargoForm");
  };

  const handleExcluirCargo = (id) =>
    setLaudo((l) => ({ ...l, cargos: (l.cargos || []).filter((c) => c.id !== id) }));

  const handleToggleCargoComplete = (id) =>
    setLaudo((l) => ({
      ...l,
      cargos: (l.cargos || []).map((c) => (c.id === id ? { ...c, complete: !c.complete } : c)),
    }));

  const handleSalvarCargo = (dadosFormulario) => {
    setLaudo((l) => ({
      ...l,
      cargos: (l.cargos || []).map((c) => (c.id === cargoAbertoId ? { ...c, ...dadosFormulario, id: c.id } : c)),
    }));
    setTela("cargos");
  };

  const cargoAberto = (laudo.cargos || []).find((c) => c.id === cargoAbertoId);
  const nomesJaAdicionados = (laudo.cargos || []).map((c) => c.nome).filter(Boolean);

  // ---------- PDF export ----------
  // O PDF é montado no aparelho (baixarPdfLaudo) e depois o laudo é registrado no histórico.

  const handleGerarPdf = () => setMostrarModalGeracao(true);

  const handleConfirmarGeracao = async (valorCobrado, manterInformacoes) => {
    const id = projetoAtualId;
    try {
      await baixarPdfLaudo(laudo);
    } catch (erro) {
      alert("Não foi possível gerar o PDF: " + (erro?.message || "erro desconhecido") + ". Verifique a internet e tente de novo.");
      return;
    }
    try {
      // Cópia completa do laudo, com as imagens como referência (cabe no Firestore)
      const { dados, envios } = await prepararLaudoParaNuvem(uid, laudo);
      const agora = new Date();
      const novoRegistro = {
        uid,
        empresaNome: laudo.dadosGerais?.empresa?.razaoSocial || "Empresa sem nome",
        projetoNome: projetos.find((pj) => pj.id === id)?.nome || "",
        profissionalNome: usuarioAtual.nome,
        profissionalEmail: usuarioAtual.email,
        data: agora.toISOString(),
        valorCobrado: valorCobrado ? valorCobrado.replace(",", ".") : "",
        laudoSnapshot: dados,
      };
      const ref = doc(collection(db, "registros"));
      envios.push(setDoc(ref, novoRegistro));
      if (manterInformacoes) {
        // Sim: o projeto continua salvo para correções
        envios.push(setDoc(refProjeto(uid, id), { laudo: dados, status: "gerado", geradoEm: agora.getTime(), atualizadoEm: agora.getTime() }, { merge: true }));
      }
      await aguardarGravacao(envios);
      setRegistros((lista) => [{ ...novoRegistro, id: ref.id }, ...lista]);
      setMostrarModalGeracao(false);

      if (manterInformacoes) {
        atualizarResumo(id, laudo, { status: "gerado", geradoEm: agora.getTime() });
        mostrarAviso("PDF baixado e laudo registrado. As informações continuam salvas neste projeto: se encontrar algum erro, corrija e gere de novo.");
      } else {
        // Não: o projeto sai da lista; o registro (com a cópia do laudo) fica no histórico
        projetosExcluidos.add(id);
        await aguardarGravacao([deleteDoc(refProjeto(uid, id))]);
        setProjetos((lista) => lista.filter((pj) => pj.id !== id));
        setProjetoAtualId(null);
        setLaudo(emptyLaudo());
        setTela("projetos");
        mostrarAviso("PDF baixado e laudo registrado. O projeto foi removido da lista; o PDF pode ser baixado de novo pelo Histórico.");
      }
    } catch (erro) {
      alert("O PDF foi baixado, mas não foi possível registrar o laudo no histórico: " + mensagemErroFirebase(erro));
    }
  };

  // ---------- Routing ----------

  const COR = tema.cor;
  const ESCURO = tema.modoEscuro;
  const BG = ESCURO ? "#0F1117" : "#F7F8FA";
  const CARD_BG = ESCURO ? "#1C2030" : "#fff";
  const TEXTO = ESCURO ? "#F0EEE6" : "#1C1F1D";
  const BORDA = ESCURO ? "#2A2D3A" : "#E5E3DC";

  if (!FIREBASE_CONFIGURADO) return <TelaFirebaseNaoConfigurado />;

  if (usuario === undefined) return <TelaCarregando cor={COR} texto="Verificando acesso..." />;
  // Quem já está conectado entra direto; a abertura aparece só antes do login
  if (usuario === null && showSplash) {
    return <TelaSplash cor={COR} onContinuar={() => setShowSplash(false)} />;
  }
  if (usuario === null) return <TelaLogin cor={COR} />;

  if (erroCarregamento) {
    return (
      <div style={{ minHeight: "100vh", background: COR, fontFamily: "Inter, sans-serif", display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
        <div style={{ maxWidth: 380, width: "100%", background: "#fff", borderRadius: 16, padding: 22, textAlign: "center" }}>
          <p style={{ fontSize: 15, fontWeight: 700, margin: "0 0 8px", color: "#1C1F1D" }}>Não foi possível carregar seus dados</p>
          <p style={{ fontSize: 13.5, color: "#44473F", margin: "0 0 18px", lineHeight: 1.5 }}>{erroCarregamento}</p>
          <button onClick={() => setTentativaCarga((n) => n + 1)} style={{ width: "100%", background: COR, color: "#fff", border: "none", borderRadius: 10, padding: 13, fontWeight: 700, fontSize: 14.5, cursor: "pointer", marginBottom: 10 }}>
            Tentar de novo
          </button>
          <button onClick={() => signOut(auth)} style={linkBtn(COR)}>Sair da conta</button>
        </div>
      </div>
    );
  }

  if (!dadosProntos) return <TelaCarregando cor={COR} texto="Carregando seus laudos..." />;

  if (perfil.aceiteTermos?.versao !== TERMOS_VERSAO) {
    return <TelaAceiteTermos cor={COR} onAceitar={aceitarTermos} onSair={() => signOut(auth)} />;
  }

  // Sem projeto aberto, a aba Laudo mostra a lista de projetos
  const telaAtual = projetoAtualId ? tela : "projetos";

  if (telaAtual === "dadosGerais") {
    return <DadosGerais dados={laudo.dadosGerais} onChange={setDadosGerais} onClose={irParaMenu} />;
  }

  if (telaAtual === "populacao") {
    return <DadosPopulacao dados={laudo.populacao} onChange={setPopulacao} onClose={irParaMenu} />;
  }

  if (telaAtual === "planoAcao") {
    return <PlanoAcao dados={laudo.planoAcao} onChange={setPlanoAcao} onClose={irParaMenu} cargos={laudo.cargos} />;
  }

  if (telaAtual === "anexos") {
    return <Anexos dados={laudo.anexos} onChange={setAnexos} onClose={irParaMenu} />;
  }

  if (telaAtual === "selecaoCargos") {
    return (
      <SelecaoCargos
        onConfirmar={handleConfirmarSelecaoCargos}
        onVoltar={() => setTela("cargos")}
        jaAdicionados={nomesJaAdicionados}
        onRemover={(nome) => setLaudo((l) => ({ ...l, cargos: (l.cargos || []).filter((c) => c.nome !== nome) }))}
        salvas={perfil.cargosPersonalizados}
        onAlterarSalvas={alterarCargosSalvos}
      />
    );
  }

  if (telaAtual === "cargoForm" && cargoAberto) {
    return (
      <CargoForm
        key={cargoAberto.id}
        initialCargo={cargoAberto}
        onSave={handleSalvarCargo}
        onClose={() => setTela("cargos")}
      />
    );
  }

  if (telaAtual === "cargos") {
    return (
      <CargoList
        cargos={laudo.cargos}
        onAdd={handleAdicionarCargoVazio}
        onOpen={handleAbrirCargo}
        onDelete={handleExcluirCargo}
        onToggleComplete={handleToggleCargoComplete}
        onSelecionarCargos={() => setTela("selecaoCargos")}
        onClose={irParaMenu}
      />
    );
  }

  const CORES_DISPONIVEIS = [
    { cor: "#0A2647", nome: "Azul Noite" },
    { cor: "#1B4332", nome: "Verde Floresta" },
    { cor: "#7A1F3D", nome: "Vinho" },
    { cor: "#5B3E9C", nome: "Roxo" },
    { cor: "#B5451B", nome: "Terracota" },
    { cor: "#1A5276", nome: "Azul Oceano" },
  ];

  const NavBar = () => (
    <div style={{
      position: "fixed", bottom: 0, left: "50%", transform: "translateX(-50%)",
      width: "100%", maxWidth: 640,
      background: CARD_BG, borderTop: `1px solid ${BORDA}`,
      display: "flex", zIndex: 100,
    }}>
      {[
        { key: "laudo", label: "Projetos", Icon: FolderOpen },
        { key: "gerados", label: "Laudos gerados", Icon: FileText },
        { key: "config", label: "Configurações", Icon: Settings },
      ].map(({ key, label, Icon }) => (
        <button key={key}
          onClick={() => { setAbaAtiva(key); if (key === "laudo") setTela(projetoAtualId ? "menu" : "projetos"); }}
          style={{
            flex: 1, display: "flex", flexDirection: "column",
            alignItems: "center", gap: 3, padding: "10px 0 14px",
            background: "none", border: "none", cursor: "pointer",
            fontFamily: "Inter, sans-serif", position: "relative",
          }}>
          <Icon size={21} color={abaAtiva === key ? COR : ESCURO ? "#6B7280" : "#9B9A90"} strokeWidth={abaAtiva === key ? 2.5 : 1.8} />
          <span style={{ fontSize: 11, fontWeight: 600, color: abaAtiva === key ? COR : ESCURO ? "#6B7280" : "#9B9A90" }}>{label}</span>
          {abaAtiva === key && (
            <div style={{ position: "absolute", bottom: 0, width: 36, height: 3, background: COR, borderRadius: 2 }} />
          )}
        </button>
      ))}
    </div>
  );

  // ---------- Aba "Laudos gerados" ----------
  if (abaAtiva === "gerados") {
    const registrosComAcao = (registros || []).map((r) => ({
      ...r,
      onAbrirArquivo: async () => {
        try {
          const restaurado = await restaurarImagens(r.laudoSnapshot || {}, r.uid || uid);
          const d = r.data ? new Date(r.data) : null;
          const dataEmissao = d && !isNaN(d) ? d.toLocaleDateString("pt-BR") : undefined;
          await baixarPdfLaudo(restaurado, { dataEmissao });
        } catch (erro) {
          alert("Não foi possível gerar o PDF deste laudo: " + (erro?.code ? mensagemErroFirebase(erro) : erro?.message || "erro desconhecido"));
        }
      },
    }));
    return (
      <>
        <Historico
          emAba
          registros={usuarioAtual.isAdmin ? registrosComAcao : registrosComAcao.filter((r) => r.uid === uid && !ocultos.has(r.id))}
          isAdmin={usuarioAtual.isAdmin}
          onReabrir={(r) => { setAbaAtiva("laudo"); reabrirRegistro(r); }}
          onExcluir={usuarioAtual.isAdmin ? null : excluirRegistroDaLista}
        />
        <NavBar />
      </>
    );
  }

  if (abaAtiva !== "config" && telaAtual === "projetos") {
    return (
      <>
        <TelaProjetos
          projetos={projetos}
          cor={COR}
          escuro={ESCURO}
          aviso={aviso}
          abrindoId={abrindoId}
          onNovo={(nome) => criarProjeto(nome)}
          onAbrir={abrirProjeto}
          onRenomear={renomearProjeto}
          onExcluir={excluirProjeto}
          onDuplicar={duplicarProjeto}
          onAbrirHistorico={() => setAbaAtiva("gerados")}
          registrosCount={usuarioAtual.isAdmin ? registros.length : meusRegistros.length}
          nomeProfissional={perfil.nome}
          onAbrirPerfil={() => setAbaAtiva("config")}
        />
        <NavBar />
      </>
    );
  }

  if (abaAtiva === "config") {
    const iniciais = perfil.nome
      ? (perfil.nome || "").split(" ").filter(Boolean).slice(0, 2).map(n => n[0]).join("").toUpperCase()
      : "?";

    return (
      <div style={{ minHeight: "100vh", background: BG, fontFamily: "Inter, sans-serif", color: TEXTO, paddingBottom: 90 }}>

        {/* Hero — avatar + nome */}
        <div style={{
          background: ESCURO
            ? "linear-gradient(160deg, #1A1D2E 0%, #252836 100%)"
            : `linear-gradient(160deg, ${COR} 0%, ${COR}CC 100%)`,
          padding: "48px 20px 32px", textAlign: "center",
        }}>
          <div style={{
            width: 72, height: 72, borderRadius: "50%",
            background: ESCURO ? "rgba(255,255,255,0.08)" : "rgba(255,255,255,0.18)",
            border: ESCURO ? "2.5px solid rgba(255,255,255,0.2)" : "2.5px solid rgba(255,255,255,0.4)",
            display: "flex", alignItems: "center", justifyContent: "center",
            margin: "0 auto 12px",
            fontFamily: "Sora, sans-serif", fontSize: 26, fontWeight: 700, color: "#fff",
          }}>{iniciais}</div>
          <h2 style={{ fontSize: 18, fontWeight: 700, color: "#fff", margin: "0 0 4px" }}>
            {perfil.nome || "Seu nome aqui"}
          </h2>
          <p style={{ fontSize: 13, color: "rgba(255,255,255,0.75)", margin: 0 }}>
            {perfil.crefito ? `CREFITO ${perfil.crefito}` : "Configure seu perfil abaixo"}
          </p>
          {isAdmin && (
            <div style={{
              display: "inline-flex", alignItems: "center", gap: 5,
              marginTop: 10, padding: "4px 12px",
              background: "rgba(255,255,255,0.18)", borderRadius: 20,
              fontSize: 11.5, fontWeight: 700, color: "#fff", letterSpacing: "0.04em",
            }}>
              ADMINISTRADOR
            </div>
          )}
        </div>

        <div style={{ maxWidth: 640, margin: "0 auto", padding: "0 16px" }}>

          {/* Perfil */}
          <ConfigSectionLabel escuro={ESCURO}>Perfil</ConfigSectionLabel>
          <ConfigCard cardBg={CARD_BG} borda={BORDA} escuro={ESCURO}>
            {[
              { label: "Nome completo", key: "nome", placeholder: "Ex.: Rafael Henrique Souza", Icon: User },
              { label: "E-mail da conta (usado para entrar)", key: "email", placeholder: "", Icon: Mail },
              { label: "CREFITO", key: "crefito", placeholder: "Ex.: 123456-F ou 123456-TO", Icon: CreditCard, isCrefito: true },
            ].map(({ label, key, placeholder, Icon, isCrefito }, i, arr) => (
              <div key={key} style={{ padding: "12px 16px", borderBottom: i < arr.length - 1 ? `1px solid ${BORDA}` : "none" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
                  <span style={{ display: "flex", alignItems: "center", color: ESCURO ? "#9B9A90" : "#44473F" }}>{Icon && <Icon size={15} />}</span>
                  <span style={{ fontSize: 12, fontWeight: 600, color: ESCURO ? "#6B7280" : "#9B9A90" }}>{label}</span>
                </div>
                {isCrefito ? (
                  <div>
                    <div style={{ position: "relative" }}>
                      <input
                        style={{
                          fontFamily: "Inter, sans-serif", fontSize: 14.5,
                          padding: "9px 40px 9px 12px",
                          border: `1.5px solid ${
                            validarCREFITO(perfil[key]) === false ? "#C0392B"
                            : validarCREFITO(perfil[key]) === true ? "#2E7D4F"
                            : BORDA}`,
                          borderRadius: 8,
                          background: validarCREFITO(perfil[key]) === false ? "#FBE8E6"
                            : validarCREFITO(perfil[key]) === true ? "#F0FAF4"
                            : ESCURO ? "#252836" : "#F7F8FA",
                          color: TEXTO, width: "100%",
                        }}
                        value={perfil[key] || ""}
                        onChange={(e) => setPerfil((p) => ({ ...p, [key]: maskCREFITO(e.target.value) }))}
                        placeholder={placeholder}
                        autoCapitalize="characters"
                      />
                      {validarCREFITO(perfil[key]) !== null && (
                        <span style={{ position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)", fontSize: 16 }}>
                          {validarCREFITO(perfil[key]) ? <Check size={15} strokeWidth={3} /> : <X size={15} strokeWidth={3} />}
                        </span>
                      )}
                    </div>
                    {validarCREFITO(perfil[key]) === false && (
                      <p style={{ fontSize: 12, color: "#C0392B", margin: "4px 0 0" }}>
                        Use: 123456-F (Fisioterapeuta) ou 123456-TO (Terapeuta Ocupacional)
                      </p>
                    )}
                    {validarCREFITO(perfil[key]) === true && (
                      <p style={{ fontSize: 12, color: "#2E7D4F", margin: "4px 0 0" }}>
                        Válido —{" "}
                        <a
                          href={`https://coffito.gov.br/nsite/?page_id=2338&numero=${(perfil[key]||"").replace(/[^0-9]/g,"")}`}
                          target="_blank" rel="noopener noreferrer"
                          style={{ color: "#2E7D4F", fontWeight: 700, textDecoration: "underline" }}
                        >
                          Verificar no COFFITO ↗
                        </a>
                      </p>
                    )}
                    {validarCREFITO(perfil[key]) === null && (
                      <p style={{ fontSize: 12, color: "#9B9A90", margin: "4px 0 0" }}>
                        Formato: 123456-F ou 123456-TO
                      </p>
                    )}
                  </div>
                ) : (
                  <input
                    style={{
                      fontFamily: "Inter, sans-serif", fontSize: 14.5,
                      padding: "9px 12px", border: `1px solid ${BORDA}`,
                      borderRadius: 8, background: ESCURO ? "#252836" : "#F7F8FA",
                      color: TEXTO, width: "100%",
                    }}
                    value={key === "email" ? (usuario?.email || "") : (perfil[key] || "")}
                    readOnly={key === "email"}
                    onChange={(e) => { if (key !== "email") setPerfil((p) => ({ ...p, [key]: e.target.value })); }}
                    placeholder={placeholder}
                  />
                )}
              </div>
            ))}
            <div style={{ padding: "12px 16px" }}>
              <button onClick={() => salvarPerfil(perfil)} disabled={perfilStatus === "salvando"} style={{
                width: "100%", background: perfilStatus === "salvo" ? "#2E7D4F" : COR, color: "#fff", border: "none",
                borderRadius: 10, padding: "13px", fontSize: 14.5, fontWeight: 700,
                fontFamily: "Inter, sans-serif", cursor: "pointer",
                boxShadow: `0 4px 12px ${COR}55`,
              }}>
                {perfilStatus === "salvando" ? "Salvando..." : perfilStatus === "salvo" ? "✓ Perfil salvo" : "Salvar perfil"}
              </button>
            </div>
          </ConfigCard>

          {/* Aparência */}
          <ConfigSectionLabel escuro={ESCURO}>Aparência</ConfigSectionLabel>
          <ConfigCard cardBg={CARD_BG} borda={BORDA} escuro={ESCURO}>
            {/* Toggle modo escuro */}
            <div style={{ padding: "14px 16px", display: "flex", alignItems: "center", justifyContent: "space-between", borderBottom: `1px solid ${BORDA}` }}>
              <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                <span style={{ width: 34, height: 34, borderRadius: 9, background: ESCURO ? "#252836" : "#F0EEE6", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 17 }}>
                  {ESCURO ? <Moon size={18} /> : <Sun size={18} />}
                </span>
                <div>
                  <p style={{ fontSize: 14, fontWeight: 600, color: TEXTO, margin: 0 }}>Modo Escuro</p>
                  <p style={{ fontSize: 12, color: "#9B9A90", margin: 0 }}>{ESCURO ? "Ativado" : "Desativado"}</p>
                </div>
              </div>
              <button onClick={() => salvarTema({ ...tema, modoEscuro: !ESCURO })} style={{
                width: 48, height: 28, borderRadius: 14, border: "none", cursor: "pointer",
                background: ESCURO ? COR : "#D8D6CD",
                position: "relative", transition: "background 0.2s", flexShrink: 0,
              }}>
                <div style={{
                  position: "absolute", top: 3,
                  left: ESCURO ? 23 : 3,
                  width: 22, height: 22, borderRadius: "50%",
                  background: "#fff",
                  boxShadow: "0 1px 3px rgba(0,0,0,0.3)",
                  transition: "left 0.2s",
                }} />
              </button>
            </div>

            {/* Cor do app */}
            <div style={{ padding: "14px 16px" }}>
              <p style={{ fontSize: 13, fontWeight: 600, color: TEXTO, margin: "0 0 12px" }}>Cor do aplicativo</p>
              <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
                {CORES_DISPONIVEIS.map(({ cor, nome }) => (
                  <button key={cor} onClick={() => salvarTema({ ...tema, cor })}
                    title={nome}
                    style={{
                      width: 40, height: 40, borderRadius: "50%",
                      background: cor, border: "none", cursor: "pointer",
                      outline: tema.cor === cor ? `3px solid ${cor}` : "3px solid transparent",
                      outlineOffset: 3,
                      boxShadow: tema.cor === cor ? `0 0 0 6px ${cor}22` : "none",
                      transition: "all 0.15s",
                      position: "relative",
                    }}>
                    {tema.cor === cor && (
                      <span style={{ color: "#fff", fontSize: 16, fontWeight: 700, lineHeight: "40px" }}>✓</span>
                    )}
                  </button>
                ))}
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 10 }}>
                <div style={{ width: 14, height: 14, borderRadius: "50%", background: COR, flexShrink: 0 }} />
                <span style={{ fontSize: 12, color: "#9B9A90" }}>
                  {CORES_DISPONIVEIS.find(c => c.cor === COR)?.nome || "Personalizada"}
                </span>
              </div>
            </div>
          </ConfigCard>

          {/* Conta */}
          <ConfigSectionLabel escuro={ESCURO}>Conta</ConfigSectionLabel>
          <ConfigCard cardBg={CARD_BG} borda={BORDA} escuro={ESCURO}>
            <div style={{ padding: "14px 16px" }}>
              <p style={{ fontSize: 13, color: "#9B9A90", margin: "0 0 12px", lineHeight: 1.5 }}>
                Conectado como <strong style={{ color: TEXTO }}>{usuario?.email}</strong>. Seus laudos ficam salvos na nuvem e aparecem em qualquer aparelho em que você entrar.
              </p>
              <button onClick={enviarLinkNovaSenha} style={{
                width: "100%", background: "none", color: TEXTO, marginBottom: 10,
                border: `1.5px solid ${BORDA}`, borderRadius: 10, padding: "12px",
                fontSize: 14, fontWeight: 700, fontFamily: "Inter, sans-serif", cursor: "pointer",
                display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
              }}>
                <Key size={16} /> Alterar senha
              </button>
              <button onClick={sairDaConta} style={{
                width: "100%", background: "none", color: TEXTO,
                border: `1.5px solid ${BORDA}`, borderRadius: 10, padding: "12px",
                fontSize: 14, fontWeight: 700, fontFamily: "Inter, sans-serif", cursor: "pointer",
              }}>
                Sair da conta
              </button>
            </div>
          </ConfigCard>

          {/* Ajuda */}
          <ConfigSectionLabel escuro={ESCURO}>Ajuda</ConfigSectionLabel>
          <ConfigCard cardBg={CARD_BG} borda={BORDA} escuro={ESCURO}>
            <button onClick={() => setDocLegalAberto("manual")} style={{
              width: "100%", display: "flex", alignItems: "center", gap: 12,
              padding: "14px 16px", background: "none", border: "none",
              cursor: "pointer", fontFamily: "Inter, sans-serif", textAlign: "left", color: TEXTO,
            }}>
              <BookOpen size={17} />
              <span style={{ flex: 1, fontSize: 14, fontWeight: 500 }}>Manual de uso</span>
              <ChevronRight size={16} color="#9B9A90" />
            </button>
          </ConfigCard>

          {/* Termos e privacidade */}
          <ConfigSectionLabel escuro={ESCURO}>Termos e privacidade</ConfigSectionLabel>
          <ConfigCard cardBg={CARD_BG} borda={BORDA} escuro={ESCURO}>
            {[
              { tipo: "termos", label: "Termos de Uso", Icon: FileText },
              { tipo: "privacidade", label: "Política de Privacidade", Icon: Shield },
            ].map(({ tipo, label, Icon }, i) => (
              <button key={tipo} onClick={() => setDocLegalAberto(tipo)} style={{
                width: "100%", display: "flex", alignItems: "center", gap: 12,
                padding: "14px 16px", background: "none", border: "none",
                borderBottom: i === 0 ? `1px solid ${BORDA}` : "none",
                cursor: "pointer", fontFamily: "Inter, sans-serif", textAlign: "left", color: TEXTO,
              }}>
                <Icon size={17} />
                <span style={{ flex: 1, fontSize: 14, fontWeight: 500 }}>{label}</span>
                <ChevronRight size={16} color="#9B9A90" />
              </button>
            ))}
            {perfil.aceiteTermos?.em && (
              <p style={{ fontSize: 11.5, color: "#9B9A90", margin: 0, padding: "0 16px 12px" }}>
                Você aceitou a versão {perfil.aceiteTermos.versao} em {new Date(perfil.aceiteTermos.em).toLocaleDateString("pt-BR")}.
              </p>
            )}
          </ConfigCard>

          <p style={{ fontSize: 11.5, color: "#9B9A90", textAlign: "center", margin: "24px 8px 8px", lineHeight: 1.6 }}>
            {AVISO_COPYRIGHT}<br />
            Uso sujeito aos Termos de Uso. É proibida a cópia, reprodução ou revenda deste software.
          </p>

          <div style={{ height: 16 }} />
        </div>
        <NavBar />
        {docLegalAberto && <DocumentoLegal tipo={docLegalAberto} onFechar={() => setDocLegalAberto(null)} cor={COR} />}
        </div>
    );
  }

  return (
    <>
      <MenuPrincipal
        laudo={laudo}
        onAbrirSecao={(key) => setTela(key === "cargos" ? "cargos" : key)}
        onGerarPdf={handleGerarPdf}
        onAbrirHistorico={() => setAbaAtiva("gerados")}
        onAbrirPerfil={() => setAbaAtiva("config")}
        nomeProfissional={perfil.nome}
        registrosCount={usuarioAtual.isAdmin ? registros.length : meusRegistros.length}
        corTema={COR}
        escuroTema={ESCURO}
        nomeProjeto={projetos.find((pj) => pj.id === projetoAtualId)?.nome}
        statusProjeto={projetos.find((pj) => pj.id === projetoAtualId)?.status}
        onSalvarESair={salvarESair}
        aviso={aviso}
      />
      {mostrarModalGeracao && (
        <ConfirmarGeracaoModal
          empresaNome={laudo.dadosGerais?.empresa?.razaoSocial}
          onConfirm={handleConfirmarGeracao}
          onCancel={() => setMostrarModalGeracao(false)}
        />
      )}
      <NavBar />
    </>
  );
}

export default AppLaudo;
